sys_script_include.script:
var CampusAssetRefQual = Class.create();

CampusAssetRefQual.prototype = {

    initialize: function() {
    },

    // Get College of logged-in Employee
    getLoggedInCollegeId: function() {

        var emp = new GlideRecord('x_1790229_edusph_0_employee');
        emp.addQuery('user', gs.getUserID());
        emp.addQuery('active', true);
        emp.setLimit(1);
        emp.query();

        if (emp.next()) {
            return emp.getValue('college');
        }

        return '';
    },

    // Holder: Reference table is sys_user
    getHolderByCollege: function() {

        var collegeId = this.getLoggedInCollegeId();

        if (!collegeId) {
            return 'sys_idINempty';
        }

        var userIds = [];

        var emp = new GlideRecord('x_1790229_edusph_0_employee');
        emp.addQuery('college', collegeId);
        emp.addQuery('active', true);
        emp.addNotNullQuery('user');
        emp.query();

        while (emp.next()) {
            userIds.push(emp.getValue('user'));
        }

        return userIds.length > 0 ?
            'sys_idIN' + userIds.join(',') :
            'sys_idINempty';
    },

    // Allocated By: Reference table is Employee
    getAllocatedByByCollege: function() {

        var collegeId = this.getLoggedInCollegeId();

        if (!collegeId) {
            return 'sys_idINempty';
        }

        return 'college=' + collegeId + '^active=true';
    },

    type: 'CampusAssetRefQual'
};
